// Atelier (Foyer): keeps French (and English, the fallback of the editor) out of
// the 82 languages of scratch-l10n, and rewrites the few French messages that
// name the brand: the Atelier is not Scratch and does not call itself so.
//
//   node traductions.cjs <scratch-editor checkout>
//
// Writes packages/scratch-gui/src/foyer/generated/{editor,paint-editor}-msgs.js
const fs = require('fs');
const path = require('path');

const root = path.resolve(process.argv[2] || '.');
const out = path.join(root, 'packages', 'scratch-gui', 'src', 'foyer', 'generated');
const KEPT = ['en', 'fr'];

// Messages of features that are still there
const REWRITTEN = {
    'gui.gui.defaultProjectTitle': 'Mon projet',
    'gui.crashMessage.description': 'Nous sommes désolés, l’Atelier a rencontré un problème. Recharge la page pour continuer.',
    'gui.unsupportedBrowser.description': 'Nous sommes désolés, ce navigateur ne permet pas d’utiliser l’Atelier. Essaie avec une version récente de Safari, Chrome, Firefox ou Edge.',
    'gui.unsupportedBrowser.notRecommended': 'Nous sommes désolés, cette version du navigateur est trop ancienne pour l’Atelier. Mets-le à jour pour continuer.',
    'gui.webglModal.description': 'Ce navigateur ou cet appareil <a>{webGlLink}</a>. L’Atelier en a besoin pour fonctionner.'
};

fs.mkdirSync(out, {recursive: true});
for (const name of ['editor-msgs', 'paint-editor-msgs']) {
    const source = fs.readFileSync(path.join(root, 'node_modules', 'scratch-l10n', 'locales', `${name}.js`), 'utf8');
    // The module is `export default {...}`: read the object without running a bundler
    const all = JSON.parse(source.slice(source.indexOf('{'), source.lastIndexOf('}') + 1));
    const kept = {};
    for (const locale of KEPT) kept[locale] = all[locale];
    for (const [key, text] of Object.entries(REWRITTEN)) if (key in kept.fr) kept.fr[key] = text;
    // What still names the brand belongs to features the Atelier does not have
    // (account, telemetry, hardware): those messages fall back to nothing shown.
    const left = Object.entries(kept.fr).filter(([, text]) => /scratch/i.test(text));
    for (const [key] of left) delete kept.fr[key];
    fs.writeFileSync(path.join(out, `${name}.js`), `// GENERATED by frontend/vendor/atelier/grands/outils/traductions.cjs (Foyer). Do not edit.\nexport default ${JSON.stringify(kept, null, 1)};\n`);
    console.log(`[atelier] ${name}: ${KEPT.join(', ')} kept, ${left.length} French messages naming the brand dropped`);
}
